int binary_search( int a[] , int le , int r, int x) {
    if( le < r ) {
        int mid = ( le + r ) / 2 ;
        if(a[ mid ] == x)
            return mid ;
        else if( x < a[ mid ] )
            return binary_search( a, le, mid, x) ;
        return binary_search( a, mid+1, r, x) ;
