int bubble_sort( int a[] , int len) {
    int count = 0;
    for(int i = 0 ; i < len ; i = i + 1 )
        for(int j = 0 ; j < len-1 ; j = j + 1 )
            if( a[j]>a[j+1] ){
                int tmp = a[j] ;
                a[j] = a[j+1] ;
                a[j+1] = tmp ;
                count = count + 1 ;
            }
    return count;
}
